local function iter(f, s, c)
  local w = coroutine.wrap(function(...)
    coroutine.yield()
    for k, v in ... do coroutine.yield(true, k, v) end
  end)

  w(f, s, c)
  return w
end

local function numfor(start, limit, step)
  local q, y = step + 0, limit + 0
  local t = start - q

  return function()
    t += q
    if (q <= 0 and t >= y) or (q > 0 and t <= y) then return true, t end
    return false
  end
end

